{
  global:
    /* [24] JSB：唯一合法的跨语言入口（Dart 走 dart:ffi） */
    Yieyu_Init; Yieyu_Shutdown; Yieyu_Post; Yieyu_Poll;
    Yieyu_Snapshot_Get; Yieyu_Service_Ping; Yieyu_Service_OnNotificationAction;
    Yieyu_Version; Yieyu_LastError; Yieyu_Stats; Yieyu_Free;
    /* [11] 防篡改 / [19][20] 存储两侧计数 */
    Yieyu_IntegrityCheck; Yieyu_SelfDigest; Yieyu_KvCount; Yieyu_StoreCount;
    /* 播放控制（能放歌的最小闭环）*/
    Yieyu_PlayUrl; Yieyu_Pause; Yieyu_Resume; Yieyu_Stop; Yieyu_SeekMs; Yieyu_SetVolume;
    /* [17] DSP 音效链 */
    Yieyu_SetDsp; Yieyu_SetEqGain; Yieyu_SetTone; Yieyu_SetRate;
    /* [9] 自研取流自检 */
    Yieyu_HttpProbe;
    /* [18] 离线人声消除 */
    Yieyu_MakeKaraoke; Yieyu_KaraokeStatus;
    /* [8] wasm 插件 */
    Yieyu_ImportPlugin; Yieyu_SetPlugin;
    /* [5] 搜歌 / 点歌（Go 网络 + 内部 URI → 真直链） */
    Yieyu_Search; Yieyu_PlaySong;
