    gesture_start; gesture_poll; gesture_down; gesture_move; gesture_up; gesture_alive;
    /* [4] 定长池自检 */
    yieyu_mem_init; yieyu_mem_alloc; yieyu_mem_free; yieyu_mem_alive; yieyu_mem_used;
    /* [22] 唯一 JNI 面：Kotlin 前台服务（只有 2 个） */
